import three;

size(200);
currentprojection = perspective(4,3,2);

triple A, B, Bp, C, D, E;
real t;

A = (sqrt(3),1,-1);
B = (sqrt(3),-1,-1);
Bp = (sqrt(3),1,1);
C = (sqrt(3),-1,1);
D = (0,0,1);
E = (0,0,-1);

